#pragma once

// Item catalog (data/catalog/items.json, generated by tools/catalog from the game paks): localized spirit /
// relic names and short explanations, spirit type, relic slot cost, icon ids. Loaded once at start; the
// tables never change at run time (no invalidation needed). UI language is English for now (v1 decision
// 2026-10-07); the file carries en-US / zh-Hans / zh-Hant / ja-JP / ko-KR.

#include <filesystem>
#include <string>
#include <vector>

namespace elmp::core::catalog {

struct Spirit {
    std::string id, name, desc, icon;
    bool main = false;
};
struct Passive {
    std::string id, name, desc, icon;
    int slots = 0;
    bool available = false;
};

std::string load(const std::filesystem::path& file); // empty = ok
bool loaded();

const Spirit* spirit(std::string_view id);
const Passive* passive(std::string_view id);
const std::vector<Spirit>& spirits();
const std::vector<Passive>& passives();

} // namespace elmp::core::catalog
